/* =====================================================================
   PART 3a — SELF-TEST HARNESS (drives the same Sim class as the app)
   ===================================================================== */
function deepFinite(o){
  if (o === null || o === undefined) return true;
  if (typeof o === 'number') return isFinite(o);
  if (typeof o === 'object'){ for (const k in o) if (!deepFinite(o[k])) return false; }
  return true;
}
function placeAtPort(sim, axialDist, closing, latOffset, latSpeed, misalignDeg, rateErrDeg){
  // position the chaser port on/near the target's port axis with prescribed contact conditions
  sim._updateContactMetrics();
  const axis = sim.contact.axis, pT = sim.contact.pT;
  let lat = V.norm(V.cross(axis, Math.abs(axis[2])<0.9?[0,0,1]:[1,0,0]));
  let qc = lookQuat(V.scl(axis,-1), Q.rot(sim.tq,[0,0,1]));
  if (misalignDeg) qc = Q.norm(Q.mul(qc, Q.fromAxisAngle([0,1,0], misalignDeg*RAD)));
  const wT_hill = Q.rot(sim.tq, sim.tw);
  let wB = Q.rotInv(qc, wT_hill);
  if (rateErrDeg) wB = V.add(wB, [rateErrDeg*RAD, 0, 0]);
  const pC = V.add(V.add(pT, V.scl(axis, axialDist)), V.scl(lat, latOffset));
  const r = V.sub(pC, Q.rot(qc, PORT_C));
  const vTport = V.cross(wT_hill, pT);
  const v = V.add(V.add(vTport, V.scl(axis, -closing)), V.scl(V.cross(axis, lat), latSpeed));
  sim._place(r, v, qc, wB, 'FINAL CORRIDOR');
}
function runSelfTestSuite(){
  const tests = [];
  const T = (name, fn) => {
    try { const r = fn(); tests.push({ name, pass: !!r.pass, detail: r.detail }); }
    catch (err){ tests.push({ name, pass:false, detail: 'exception: ' + err.message }); }
  };

  T('1 · propagated state stays finite', () => {
    const s = new Sim(11, 'nominal');
    s.advance(90);
    const ok = deepFinite(s.snapshot());
    return { pass: ok, detail: ok ? '90 s propagated; every snapshot field finite' : 'non-finite value found in snapshot' };
  });

  T('2 · pause halts sim time and state', () => {
    const s = new Sim(12, 'nominal'); s.advance(10);
    const eng = new Engine(s); eng.paused = true;
    const before = JSON.stringify(s.snapshot()); const t0 = s.t;
    for (let i=0;i<50;i++) eng.tick(0.1);
    const same = s.t === t0 && JSON.stringify(s.snapshot()) === before;
    return { pass: same, detail: same ? `t held at ${t0.toFixed(2)} s across 50 paused engine ticks` : 'state advanced while paused' };
  });

  T('3 · same seed + inputs ⇒ identical run', () => {
    const a = new Sim(42, 'nominal'); a.advance(40);
    const b = new Sim(42, 'nominal'); for (let i=0;i<80;i++) b.advance(0.5);
    const eq = JSON.stringify(a.snapshot()) === JSON.stringify(b.snapshot());
    return { pass: eq, detail: eq ? '40 s runs (1×40 s vs 80×0.5 s chunks) bit-identical' : 'snapshots diverged' };
  });

  T('4 · propellant never increases', () => {
    const s = new Sim(13, 'nominal');
    let prev = s.prop, ok = true;
    for (let i=0;i<240;i++){ s.advance(0.5); if (s.prop > prev + 1e-12){ ok = false; break; } prev = s.prop; }
    return { pass: ok, detail: ok ? `monotonic over 120 s of active control (${(PROP0-s.prop).toFixed(3)} kg burned)` : 'propellant increased' };
  });

  T('5 · failed thruster gives zero achieved impulse', () => {
    const s = new Sim(14, 'nominal');
    s.auto = false; s.manualCmd.F = [1,0,0];
    s.setFault('thruster', true, 0);
    s.advance(5);
    const th = s.thr[0];
    const pass = th.cmdTot > 0.5 && th.achTot === 0;
    return { pass, detail: `jet A1 commanded ${th.cmdTot.toFixed(1)} N·s, achieved ${th.achTot.toFixed(1)} N·s` };
  });

  T('6 · sensor blackout cannot shrink uncertainty', () => {
    const s = new Sim(15, 'nominal');
    s.advance(40);
    const sig1 = s.est.sigPos;
    s.setFault('lidar', true); s.setFault('optical', true);
    s.advance(30);
    const sig2 = s.est.sigPos;
    const pass = sig2 >= sig1 * 0.999;
    return { pass, detail: `σ ${sig1.toFixed(3)} m → ${sig2.toFixed(3)} m over 30 s blind (must not decrease)` };
  });

  T('7 · abort produces a safe retreat trend', () => {
    const s = new Sim(16, 'nominal');
    s._place([0,-60,0], [0,0,0], null, null, 'HOLD POINT');
    const r0 = V.len(s.r);
    s.abort('self-test abort command');
    s.advance(150);
    const r1 = V.len(s.r);
    const pass = r1 > r0 + 10 && (s.phase === 'ABORT' || s.phase === 'SAFE HOLD');
    return { pass, detail: `range ${r0.toFixed(0)} m → ${r1.toFixed(0)} m, phase ${s.phase}` };
  });

  T('8 · docking rejected outside contact limits', () => {
    const s = new Sim(17, 'nominal');
    s.auto = false;                                  // ballistic: no guidance rescue
    placeAtPort(s, 0.45, 0.30, 0.20, 0.05, 9, 1.5);  // too fast, off-axis, misaligned
    for (let i=0;i<60 && !s.lastContact;i++) s.advance(0.25);
    const lc = s.lastContact;
    const pass = !!lc && lc.rejected === true && !s.docked && !s.captured;
    return { pass, detail: lc ? `contact rejected (closing ${lc.metrics.closing.toFixed(2)} m/s, lat ${lc.metrics.lateral.toFixed(2)} m, align ${lc.metrics.align.toFixed(1)}°) — vehicle bounced` : 'no contact occurred' };
  });

  T('9 · nominal soft capture → hard dock in limits', () => {
    const s = new Sim(18, 'nominal');
    placeAtPort(s, 0.9, 0.045, 0.01, 0, 0.5, 0);     // clean final-corridor conditions
    let sawSoft = false;
    for (let i=0;i<600 && !s.docked;i++){ s.advance(0.25); if (s.phase === 'SOFT CAPTURE') sawSoft = true; }
    const pass = sawSoft && s.docked;
    return { pass, detail: pass ? `soft capture at gates, hard dock at t=${s.t.toFixed(1)} s` : `phase ${s.phase}, docked=${s.docked}, soft=${sawSoft}` };
  });

  return { passed: tests.every(t => t.pass), tests };
}

