/* ---------- Earth + atmosphere + stars + sun ---------- */
const NOISE_GLSL = `
float hash3(vec3 p){ p = fract(p*0.3183099 + vec3(0.71,0.113,0.419)); p *= 17.0;
  return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float vnoise(vec3 p){ vec3 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);
  return mix(mix(mix(hash3(i), hash3(i+vec3(1,0,0)), f.x), mix(hash3(i+vec3(0,1,0)), hash3(i+vec3(1,1,0)), f.x), f.y),
             mix(mix(hash3(i+vec3(0,0,1)), hash3(i+vec3(1,0,1)), f.x), mix(hash3(i+vec3(0,1,1)), hash3(i+vec3(1,1,1)), f.x), f.y), f.z); }
float fbm(vec3 p){ float a = 0.5, r = 0.0; for (int i=0;i<5;i++){ r += a*vnoise(p); p *= 2.13; a *= 0.5; } return r; }`;

function buildEarth(){
  const grp = new THREE.Group();
  grp.position.set(0, -(RE+ALT), 0);
  const uniforms = {
    uSun: { value: new THREE.Vector3(1,0,0) },
    uTime: { value: 0 },
    uCamPos: { value: new THREE.Vector3() },
  };
  const earthMat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: `
      varying vec3 vN; varying vec3 vL; varying vec3 vW;
      void main(){
        vL = normalize(position);
        vN = normalize(mat3(modelMatrix) * normal);
        vec4 wp = modelMatrix * vec4(position, 1.0); vW = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: `
      precision highp float;
      varying vec3 vN; varying vec3 vL; varying vec3 vW;
      uniform vec3 uSun; uniform float uTime; uniform vec3 uCamPos;
      ${NOISE_GLSL}
      void main(){
        vec3 n = normalize(vN);
        float cont = fbm(vL*2.1 + vec3(3.7));
        float land = smoothstep(0.52, 0.56, cont);
        float lat = abs(vL.y);
        float ice = smoothstep(0.86, 0.94, lat + 0.16*(cont-0.5));
        float detail = fbm(vL*7.0 + vec3(9.1));
        vec3 ocean = mix(vec3(0.012,0.06,0.14), vec3(0.02,0.11,0.22), detail);
        vec3 landC = mix(vec3(0.05,0.14,0.04), vec3(0.35,0.28,0.13), smoothstep(0.3,0.75,detail + 0.5*(lat-0.3)));
        vec3 col = mix(ocean, landC, land);
