/* ---------- spacecraft ---------- */
function addNozzles(group, defs, scale=1){
  const mat = new THREE.MeshStandardMaterial({ color: 0x2c3138, roughness: 0.45, metalness: 0.85 });
  const inner = new THREE.MeshStandardMaterial({ color: 0x14161a, roughness: 0.9, metalness: 0.2 });
  for (const d of defs){
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055*scale, 0.14*scale, 12, 1, true), mat);
    // exhaust points opposite thrust dir: cone opening (base) faces -dir
