  const hull = new THREE.Mesh(new THREE.CylinderGeometry(1.05, 1.05, 3.6, 22), scorch);
  hull.rotation.z = Math.PI/2; g.add(hull);
  const nose = new THREE.Mesh(new THREE.CylinderGeometry(0.75, 1.05, 0.6, 22), gray);
