  const aft = new THREE.Mesh(new THREE.SphereGeometry(1.05, 22, 12, 0, Math.PI*2, Math.PI/2, Math.PI/2), dark);
  aft.rotation.z = Math.PI/2; aft.position.x = -1.8; g.add(aft);

  // docking port +X with visual docking target (base plate + stand-off cross)
