  const plate = new THREE.Mesh(new THREE.CircleGeometry(0.26, 20),
    new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.8, metalness: 0.2 }));
  plate.rotation.y = Math.PI/2; plate.position.x = 2.06; g.add(plate);
  const cross1 = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.28, 0.035),
    new THREE.MeshStandardMaterial({ color: 0xcccccc, emissive: 0x99ffbb, emissiveIntensity: 0.35 }));
  cross1.position.x = 2.22; g.add(cross1);
  const cross2 = cross1.clone(); cross2.rotation.x = Math.PI/2; g.add(cross2);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.16, 6), steel);
