  const stubArm = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.6, 8), steel);
  stubArm.position.set(0.2, -1.25, 0); g.add(stubArm);
  for (let i=0;i<5;i++){ // torn fragments
    const frag = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.4, 0.02),
      new THREE.MeshStandardMaterial({ map: solTex, roughness: 0.5, metalness: 0.5, side: THREE.DoubleSide }));
    frag.position.set(0.1 + visRand.uniform()*0.3, -1.6 - i*0.12, (visRand.uniform()-0.5)*0.3);
    frag.rotation.set(visRand.uniform()*1.2, visRand.uniform()*0.8, visRand.uniform()*1.2);
    g.add(frag);
  }
  // bent dish, dead antennas
  const dish = new THREE.Mesh(new THREE.SphereGeometry(0.35, 16, 10, 0, Math.PI*2, 0, 1.0), gray);
  dish.position.set(-0.8, 0, 1.25); dish.rotation.x = 1.9; g.add(dish);
  const bentBoom = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.8, 8), steel);
  bentBoom.position.set(-0.8, 0, 1.0); bentBoom.rotation.y = 0.4; bentBoom.rotation.x = 0.5; g.add(bentBoom);
  // fault beacon (amber, slow blink — driven per frame)
  world.beacon = new THREE.Mesh(new THREE.SphereGeometry(0.06, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x111111, emissive: 0xffaa22, emissiveIntensity: 0 }));
  world.beacon.position.set(-1.2, 0, 1.12); g.add(world.beacon);
  g.traverse(o => { if (o.isMesh){ o.castShadow = true; o.receiveShadow = true; } });
  return g;
}

/* ---------- overlay objects ---------- */
function buildOverlays(){
  const ov = {};
  // LVLH axes at target
  ov.axes = new THREE.Group();
  const mkAxis = (dirScene, color, label) => {
    const ar = new THREE.ArrowHelper(dirScene, new THREE.Vector3(), 24, color, 3.5, 1.6);
    ov.axes.add(ar);
    const sp = makeTextSprite(label, '#' + color.toString(16).padStart(6,'0'));
    sp.position.copy(dirScene).multiplyScalar(28); sp.scale.set(7,1.75,1);
    ov.axes.add(sp);
  };
  mkAxis(new THREE.Vector3(1,0,0), 0x5fdc95, 'V-BAR');      // along-track
  mkAxis(new THREE.Vector3(0,1,0), 0x56d4ec, 'R-BAR');      // radial out (zenith)
  mkAxis(new THREE.Vector3(0,0,1), 0xf2c14e, 'H-BAR');      // cross-track
  // trajectory trail
  const trailGeo = new THREE.BufferGeometry();
  trailGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(2400*3), 3));
  trailGeo.setDrawRange(0, 0);
  ov.trail = new THREE.Line(trailGeo, new THREE.LineBasicMaterial({ color: 0x56d4ec, transparent: true, opacity: 0.75 }));
  ov.trail.frustumCulled = false;
  ov.trailCount = 0; ov.trailLastT = -1;
  // predicted path
  const predGeo = new THREE.BufferGeometry();
  predGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(64*3), 3));
  ov.pred = new THREE.Line(predGeo, new THREE.LineDashedMaterial({ color: 0xd8b4ff, dashSize: 3, gapSize: 2, transparent: true, opacity: 0.8 }));
  ov.pred.frustumCulled = false;
  // keep-out sphere
  ov.kos = new THREE.Group();
  const kosWire = new THREE.Mesh(new THREE.SphereGeometry(KOS_R, 28, 18),
    new THREE.MeshBasicMaterial({ color: 0xff7a5c, wireframe: true, transparent: true, opacity: 0.16 }));
  const kosFill = new THREE.Mesh(new THREE.SphereGeometry(KOS_R, 28, 18),
    new THREE.MeshBasicMaterial({ color: 0xff5c40, transparent: true, opacity: 0.03, side: THREE.BackSide, depthWrite: false }));
  ov.kos.add(kosWire, kosFill);
  ov.kosWire = kosWire; ov.kosFill = kosFill;
  const kosLabel = makeTextSprite('KEEP-OUT 30 m', '#ff9a80'); kosLabel.position.set(0, KOS_R+3, 0); kosLabel.scale.set(11,2.75,1);
  ov.kos.add(kosLabel);
  // approach corridor cone (repositioned every frame from the live port axis)
  ov.corridor = new THREE.Group();
  const corLen = 42, corR = Math.tan(CORR_HALF)*corLen;
  const cone = new THREE.Mesh(new THREE.ConeGeometry(corR, corLen, 20, 6, true),
    new THREE.MeshBasicMaterial({ color: 0x5fdc95, wireframe: true, transparent: true, opacity: 0.12, depthWrite: false }));
  ov.corridorCone = cone; ov.corridor.add(cone);
  const axisPts = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3(0, corLen, 0)]);
  const axisLine = new THREE.Line(axisPts, new THREE.LineDashedMaterial({ color: 0x5fdc95, dashSize: 1.2, gapSize: 0.8, transparent: true, opacity: 0.6 }));
  axisLine.computeLineDistances(); cone.add(axisLine);
  axisLine.position.y = -corLen/2;
  // sensor rays
  ov.sensors = new THREE.Group();
  const lidarGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
  ov.lidarRay = new THREE.Line(lidarGeo, new THREE.LineDashedMaterial({ color: 0x54ff8a, dashSize: 2.4, gapSize: 1.6, transparent: true, opacity: 0.85 }));
  ov.lidarRay.frustumCulled = false;
  ov.sensors.add(ov.lidarRay);
  ov.optCone = new THREE.Mesh(new THREE.ConeGeometry(Math.tan(8*RAD)*30, 30, 16, 1, true),
    new THREE.MeshBasicMaterial({ color: 0x56d4ec, transparent: true, opacity: 0.05, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
  ov.sensors.add(ov.optCone);
  // covariance ellipsoid (3σ)
  ov.cov = new THREE.Group();
  const covMesh = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14),
    new THREE.MeshBasicMaterial({ color: 0xd8b4ff, transparent: true, opacity: 0.14, blending: THREE.AdditiveBlending, depthWrite: false }));
  const covWire = new THREE.Mesh(new THREE.SphereGeometry(1, 12, 8),
    new THREE.MeshBasicMaterial({ color: 0xd8b4ff, wireframe: true, transparent: true, opacity: 0.28 }));
  ov.cov.add(covMesh, covWire);
  // velocity vector
  ov.vel = new THREE.ArrowHelper(new THREE.Vector3(1,0,0), new THREE.Vector3(), 5, 0xf2c14e, 1.4, 0.7);
  // docking guides: range rings along the corridor + port-to-port tether
  ov.guides = new THREE.Group();
  ov.guideRings = [];
  for (const s of [2, 5, 10, 20, 30]){
    const rr = Math.max(Math.tan(CORR_HALF)*s*0.9, 0.45);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(rr, Math.max(0.02, rr*0.02), 8, 40),
      new THREE.MeshBasicMaterial({ color: 0x9fe8f5, transparent: true, opacity: 0.4, depthWrite: false }));
    const tick = new THREE.Mesh(new THREE.BoxGeometry(rr*0.35, 0.03, 0.03),
      new THREE.MeshBasicMaterial({ color: 0xf2c14e, transparent: true, opacity: 0.8 }));
    tick.position.x = rr*0.8;
    ring.add(tick);
    const lbl = makeTextSprite(`${s} m`, '#9fe8f5'); lbl.scale.set(2.4,0.6,1); lbl.position.set(0, rr+0.5, 0);
    ring.add(lbl);
    ov.guides.add(ring);
    ov.guideRings.push({ mesh: ring, s });
  }
  const tetherGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
  ov.tether = new THREE.Line(tetherGeo, new THREE.LineBasicMaterial({ color: 0xf2c14e, transparent: true, opacity: 0.7 }));
  ov.tether.frustumCulled = false;
  ov.guides.add(ov.tether);
  return ov;
}

/* ---------- renderer bootstrap ---------- */
function initThree(container){
  try {
    renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  } catch (err){
    return { ok: false, err };
  }
  if (!renderer.getContext()) return { ok: false, err: new Error('no WebGL context') };
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  container.appendChild(renderer.domElement);

  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x000104);
  camera = new THREE.PerspectiveCamera(55, 1, 0.05, 6e7);
  camera.position.set(-14, 6, 12);

  world.earth = buildEarth(); scene.add(world.earth);
  const stars = buildStars(); world.stars = stars.grp; scene.add(stars.grp); scene.add(stars.sun);
  world.chaser = buildChaser(); scene.add(world.chaser);
  world.target = buildTarget(); scene.add(world.target);

  world.sun = new THREE.DirectionalLight(0xfff2dd, 3.0);
  world.sun.castShadow = true;
  world.sun.shadow.mapSize.set(1024, 1024);
  const sc = world.sun.shadow.camera;
  sc.near = 1; sc.far = 400; sc.left = sc.bottom = -50; sc.right = sc.top = 50;
  scene.add(world.sun); scene.add(world.sun.target);
  world.earthshine = new THREE.DirectionalLight(0x3f6288, 0.35);
  world.earthshine.position.set(0, -1, 0); scene.add(world.earthshine);
  world.hemi = new THREE.HemisphereLight(0x1c2836, 0x05070a, 0.3); scene.add(world.hemi);

  world.ov = buildOverlays();
  const ov = world.ov;
  scene.add(ov.axes, ov.trail, ov.pred, ov.kos, ov.corridor, ov.sensors, ov.cov, ov.vel, ov.guides);
  return { ok: true };
}

/* ---------- per-frame scene sync (all pose data comes from the sim) ---------- */
const _tmpV = new THREE.Vector3(), _tmpV2 = new THREE.Vector3();
let _predClock = 0;
function updateScene(sim, dtWall, ovState, reduced){
  const t = sim.t;
  world.chaser.position.copy(h2s(sim.r));
  world.chaser.quaternion.copy(quatToScene(sim.q));
  world.target.quaternion.copy(quatToScene(sim.tq));

  // sun / eclipse / earth rotation
  const sd = sim.sunDir || [Math.cos(40*RAD)*Math.cos(22*RAD), Math.sin(40*RAD)*Math.cos(22*RAD), Math.sin(22*RAD)];
  const sunScene = h2s(sd);
  const lit = sim.sens.litFrac !== undefined ? sim.sens.litFrac : 1;
  world.sun.position.copy(sunScene).multiplyScalar(200);
  world.sun.target.position.set(0,0,0);
  world.sun.intensity = 0.06 + 3.0 * lit;
  world.earthshine.intensity = 0.06 + 0.34 * lit;
  world.hemi.intensity = 0.12 + 0.2 * lit;
  world.sunSprite.position.copy(sunScene).multiplyScalar(2.2e7);
  world.earthUniforms.uSun.value.copy(sunScene);
  world.earthUniforms.uTime.value = t;
  world.earthUniforms.uCamPos.value.copy(camera.position);
  world.earth.rotation.z = N_ORB * t * 0.94;
  world.stars.rotation.z = N_ORB * t;

  // nav lights & beacon (deterministic sim-time blink)
  const strobe = (t % 2) < 0.12 ? 3.5 : 0;
  world.navStrobe.material.emissiveIntensity = reduced ? 1.2 : strobe;
  world.navRed.material.emissiveIntensity = 1.2 + (reduced ? 0 : 0.8*Math.sin(t*2.5));
  world.navGrn.material.emissiveIntensity = 1.2 + (reduced ? 0 : 0.8*Math.sin(t*2.5+1.6));
  world.beacon.material.emissiveIntensity = (t % 3) < 0.25 ? 3 : 0.05;
  world.lidarApMat.emissiveIntensity = sim.sens.lidar ? (reduced ? 0.6 : 0.3 + 0.5*Math.abs(Math.sin(t*6))) : 0.05;

  // plumes from live duty cycles
  for (let i=0;i<16;i++){
    const p = world.plumes[i], th = sim.thr[i];
    const firing = th.duty > 0 && th.achImp > 0;
    const f = firing ? th.duty * (reduced ? 0.85 : 0.7 + 0.3*visRand.uniform()) : 0;
    p.material.opacity = f * 0.85;
    p.scale.set(0.7 + f*0.6, 0.4 + f*0.9, 0.7 + f*0.6);
  }

  const ov = world.ov, c = sim.contact;
  ov.axes.visible = ovState.axes;
  ov.kos.visible = ovState.kos;
  ov.trail.visible = ovState.trail;
  ov.pred.visible = ovState.pred;
  ov.corridor.visible = ovState.corridor;
  ov.sensors.visible = ovState.sensors;
  ov.cov.visible = ovState.cov;
  ov.vel.visible = ovState.vel;
  ov.guides.visible = ovState.guides && !!c;
  world.rcsLabels.visible = ovState.rcs;

  // KOS breach visual: solid + label pulse (shape/opacity change, not colour alone)
  const inCorrPhase = sim.phase === 'FINAL CORRIDOR' || sim.phase === 'SOFT CAPTURE' || sim.phase === 'HARD DOCK';
  const breach = V.len(sim.r) < KOS_R && !inCorrPhase && !sim.docked;
  ov.kosWire.material.opacity = breach ? 0.45 : 0.16;
  ov.kosFill.material.opacity = breach ? 0.10 : 0.03;

  // trail (reset-aware)
  if (t < ov.trailLastT){ ov.trailCount = 0; ov.pred.geometry.setDrawRange(0,0); }
  if (ovState.trail && (t - ov.trailLastT > 1.5 || ov.trailLastT < 0)){
    ov.trailLastT = t;
    const attr = ov.trail.geometry.attributes.position;
    if (ov.trailCount >= 2400){ attr.array.copyWithin(0, 3*600); ov.trailCount -= 600; }
    const p = h2s(sim.r);
    attr.array[ov.trailCount*3] = p.x; attr.array[ov.trailCount*3+1] = p.y; attr.array[ov.trailCount*3+2] = p.z;
    ov.trailCount++;
    attr.needsUpdate = true;
    ov.trail.geometry.setDrawRange(0, ov.trailCount);
  }
  if (t < ov.trailLastT) ov.trailLastT = t;

  // predicted drift path (from the *estimate*, CW closed form)
  _predClock += dtWall;
  if (ovState.pred && _predClock > 0.4){
    _predClock = 0;
    const attr = ov.pred.geometry.attributes.position;
    const N = 64, T = 1500;
    for (let i=0;i<N;i++){
      const p = h2s(cwPropagate(sim.est.r, sim.est.v, (i/(N-1))*T));
      attr.array[i*3]=p.x; attr.array[i*3+1]=p.y; attr.array[i*3+2]=p.z;
    }
    attr.needsUpdate = true;
    ov.pred.geometry.setDrawRange(0, N);
    ov.pred.computeLineDistances();
  }

  if (c){
    const axisS = h2s(c.axis), pTS = h2s(c.pT), pCS = h2s(c.pC);
    // corridor cone: apex at target port, opening outward
    ov.corridorCone.quaternion.setFromUnitVectors(_tmpV.set(0,1,0), _tmpV2.copy(axisS).negate().normalize());
    ov.corridorCone.position.copy(pTS).addScaledVector(axisS, 21);
