    for (const gr of ov.guideRings){
      gr.mesh.position.copy(pTS).addScaledVector(axisS, gr.s);
      gr.mesh.quaternion.copy(world.target.quaternion);
      gr.mesh.rotateY(Math.PI/2);
    }
    const ta = ov.tether.geometry.attributes.position;
    ta.array[0]=pCS.x; ta.array[1]=pCS.y; ta.array[2]=pCS.z;
    ta.array[3]=pTS.x; ta.array[4]=pTS.y; ta.array[5]=pTS.z;
    ta.needsUpdate = true;
  }

  // sensor rays
  if (ovState.sensors){
    ov.lidarRay.visible = sim.sens.lidar;
    const la = ov.lidarRay.geometry.attributes.position;
    const cp = world.chaser.position;
    la.array[0]=cp.x; la.array[1]=cp.y; la.array[2]=cp.z; la.array[3]=0; la.array[4]=0; la.array[5]=0;
    la.needsUpdate = true;
    ov.lidarRay.computeLineDistances();
    ov.lidarRay.material.dashOffset = reduced ? 0 : -(t*8 % 100);
    ov.optCone.visible = sim.sens.optical;
    if (sim.sens.optical){
      _tmpV.copy(world.chaser.position).negate().normalize();     // toward target
      ov.optCone.quaternion.setFromUnitVectors(_tmpV2.set(0,-1,0), _tmpV);
      ov.optCone.position.copy(world.chaser.position).addScaledVector(_tmpV, 15);
