  if (ovState.cov){
    const P = sim.est.P;
    const eig = eigenSym3([P[0][0],P[0][1],P[0][2], P[1][0],P[1][1],P[1][2], P[2][0],P[2][1],P[2][2]]);
    const s1 = 3*Math.sqrt(Math.max(eig.val[0],1e-8)), s2 = 3*Math.sqrt(Math.max(eig.val[1],1e-8)), s3 = 3*Math.sqrt(Math.max(eig.val[2],1e-8));
    const bx = h2s(eig.vec[0]).multiplyScalar(1), by = h2s(eig.vec[1]), bz = h2s(eig.vec[2]);
