    const m = new THREE.Matrix4().makeBasis(bx.normalize(), by.normalize(), bx.clone().cross(by).normalize());
    ov.cov.quaternion.setFromRotationMatrix(m);
    ov.cov.scale.set(Math.max(s1,0.05), Math.max(s2,0.05), Math.max(s3,0.05));
    ov.cov.position.copy(h2s(sim.est.r));
  }

  // velocity vector
  if (ovState.vel){
    const vlen = V.len(sim.v);
    ov.vel.position.copy(world.chaser.position);
    if (vlen > 1e-4){
      ov.vel.setDirection(h2s(V.norm(sim.v)));
      ov.vel.setLength(clamp(vlen*40, 1.5, 60), 1.4, 0.7);
    }
  }
}
