  g.fillStyle = color; g.fillText(text, 128, 34);
  const tx = new THREE.CanvasTexture(cv); tx.colorSpace = THREE.SRGBColorSpace;
  const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: tx, transparent: true, depthWrite: false }));
  sp.scale.set(4, 1, 1);
  return sp;
}

/* ---------- Earth + atmosphere + stars + sun ---------- */
const NOISE_GLSL = `
float hash3(vec3 p){ p = fract(p*0.3183099 + vec3(0.71,0.113,0.419)); p *= 17.0;
  return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float vnoise(vec3 p){ vec3 i = floor(p), f = fract(p); f = f*f*(3.0-2.0*f);
  return mix(mix(mix(hash3(i), hash3(i+vec3(1,0,0)), f.x), mix(hash3(i+vec3(0,1,0)), hash3(i+vec3(1,1,0)), f.x), f.y),
             mix(mix(hash3(i+vec3(0,0,1)), hash3(i+vec3(1,0,1)), f.x), mix(hash3(i+vec3(0,1,1)), hash3(i+vec3(1,1,1)), f.x), f.y), f.z); }
float fbm(vec3 p){ float a = 0.5, r = 0.0; for (int i=0;i<5;i++){ r += a*vnoise(p); p *= 2.13; a *= 0.5; } return r; }`;

function buildEarth(){
  const grp = new THREE.Group();
  grp.position.set(0, -(RE+ALT), 0);
  const uniforms = {
    uSun: { value: new THREE.Vector3(1,0,0) },
    uTime: { value: 0 },
    uCamPos: { value: new THREE.Vector3() },
  };
  const earthMat = new THREE.ShaderMaterial({
    uniforms,
    vertexShader: `
      varying vec3 vN; varying vec3 vL; varying vec3 vW;
      void main(){
        vL = normalize(position);
        vN = normalize(mat3(modelMatrix) * normal);
        vec4 wp = modelMatrix * vec4(position, 1.0); vW = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }`,
    fragmentShader: `
      precision highp float;
      varying vec3 vN; varying vec3 vL; varying vec3 vW;
      uniform vec3 uSun; uniform float uTime; uniform vec3 uCamPos;
      ${NOISE_GLSL}
      void main(){
        vec3 n = normalize(vN);
        float cont = fbm(vL*2.1 + vec3(3.7));
        float land = smoothstep(0.52, 0.56, cont);
        float lat = abs(vL.y);
        float ice = smoothstep(0.86, 0.94, lat + 0.16*(cont-0.5));
        float detail = fbm(vL*7.0 + vec3(9.1));
        vec3 ocean = mix(vec3(0.012,0.06,0.14), vec3(0.02,0.11,0.22), detail);
        vec3 landC = mix(vec3(0.05,0.14,0.04), vec3(0.35,0.28,0.13), smoothstep(0.3,0.75,detail + 0.5*(lat-0.3)));
        vec3 col = mix(ocean, landC, land);
        col = mix(col, vec3(0.85,0.88,0.92), ice);
        float cl = fbm(vL*4.4 + vec3(uTime*0.0035, 0.0, uTime*0.002));
        cl = smoothstep(0.48, 0.75, cl);
        col = mix(col, vec3(0.86,0.88,0.91), cl*0.85);
        float day = clamp(dot(n, uSun), 0.0, 1.0);
        float dusk = smoothstep(-0.18, 0.12, dot(n, uSun));
        vec3 vdir = normalize(uCamPos - vW);
        float glint = pow(max(dot(reflect(-uSun, n), vdir), 0.0), 90.0) * (1.0-land) * (1.0-cl) * day;
        float night = 1.0 - dusk;
        float city = smoothstep(0.63, 0.75, fbm(vL*9.0 + vec3(5.5))) * land * night * (1.0-ice) * (1.0-cl*0.8);
        vec3 sunset = vec3(0.9,0.45,0.15) * pow(dusk*(1.0-dusk)*4.0, 2.5) * 0.35;
        vec3 outc = col * (0.012 + 1.35*day*dusk) + glint*vec3(0.9,0.85,0.7)*0.8
                  + city*vec3(1.0,0.75,0.4)*0.65 + sunset;
        gl_FragColor = vec4(outc, 1.0);
      }`,
  });
  const earth = new THREE.Mesh(new THREE.SphereGeometry(RE, 96, 64), earthMat);
  grp.add(earth);
  const atmoMat = new THREE.ShaderMaterial({
    uniforms, side: THREE.BackSide, transparent: true, depthWrite: false,
    blending: THREE.AdditiveBlending,
    vertexShader: `
      varying vec3 vN; varying vec3 vW;
      void main(){ vN = normalize(mat3(modelMatrix)*normal);
        vec4 wp = modelMatrix*vec4(position,1.0); vW = wp.xyz;
        gl_Position = projectionMatrix*viewMatrix*wp; }`,
    fragmentShader: `
      precision highp float;
      varying vec3 vN; varying vec3 vW;
      uniform vec3 uSun; uniform vec3 uCamPos;
      void main(){
        vec3 n = normalize(vN);
        vec3 vdir = normalize(uCamPos - vW);
        float rim = pow(clamp(1.0 + dot(vdir, n), 0.0, 1.0), 3.2);
        float day = clamp(dot(n, uSun)*0.9 + 0.25, 0.0, 1.0);
        vec3 col = mix(vec3(0.02,0.05,0.12), vec3(0.25,0.55,1.0), day);
        gl_FragColor = vec4(col * rim * 1.35, rim);
      }`,
  });
  grp.add(new THREE.Mesh(new THREE.SphereGeometry(RE*1.02, 64, 48), atmoMat));
  world.earthUniforms = uniforms;
  return grp;
}
function buildStars(){
  const grp = new THREE.Group();
  const mk = (count, spread, sizePx, opac) => {
    const pos = new Float32Array(count*3), col = new Float32Array(count*3);
    for (let i=0;i<count;i++){
      let p;
      if (spread === 'band'){
        const th = visRand.uniform()*Math.PI*2, off = (visRand.gauss())*0.18;
        p = new THREE.Vector3(Math.cos(th), off, Math.sin(th)).normalize();
        p.applyAxisAngle(new THREE.Vector3(1,0,0.4).normalize(), 1.05);
      } else {
        p = new THREE.Vector3(visRand.gauss(), visRand.gauss(), visRand.gauss()).normalize();
      }
      p.multiplyScalar(2.4e7);
      pos.set([p.x,p.y,p.z], i*3);
      const t = visRand.uniform();
      const c = t<0.7 ? [1,1,1] : (t<0.85 ? [1,0.85,0.7] : [0.75,0.85,1]);
      const b = 0.5 + visRand.uniform()*0.5;
      col.set([c[0]*b, c[1]*b, c[2]*b], i*3);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos,3));
    geo.setAttribute('color', new THREE.BufferAttribute(col,3));
    const mat = new THREE.PointsMaterial({ size: sizePx, sizeAttenuation:false, vertexColors:true,
      transparent:true, opacity:opac, depthWrite:false });
    return new THREE.Points(geo, mat);
  };
  grp.add(mk(2200, 'iso', 1.6, 0.95));
  grp.add(mk(1600, 'band', 1.1, 0.55));
  const sunTex = makeCanvasTex(128, (g,s)=>{
    const gr = g.createRadialGradient(s/2,s/2,2,s/2,s/2,s/2);
    gr.addColorStop(0,'rgba(255,252,240,1)'); gr.addColorStop(0.18,'rgba(255,240,200,.95)');
    gr.addColorStop(0.5,'rgba(255,200,120,.22)'); gr.addColorStop(1,'rgba(255,180,90,0)');
    g.fillStyle = gr; g.fillRect(0,0,s,s);
  });
  const sun = new THREE.Sprite(new THREE.SpriteMaterial({ map: sunTex, transparent:true, depthWrite:false }));
  sun.scale.set(3.2e6, 3.2e6, 1);
  world.sunSprite = sun;
  return { grp, sun };
}

/* ---------- spacecraft ---------- */
function addNozzles(group, defs, scale=1){
  const mat = new THREE.MeshStandardMaterial({ color: 0x2c3138, roughness: 0.45, metalness: 0.85 });
  const inner = new THREE.MeshStandardMaterial({ color: 0x14161a, roughness: 0.9, metalness: 0.2 });
  for (const d of defs){
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055*scale, 0.14*scale, 12, 1, true), mat);
    // exhaust points opposite thrust dir: cone opening (base) faces -dir
    const dir = new THREE.Vector3(...d.dir);
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0,-1,0), dir.clone().negate());
    cone.position.set(...d.pos).addScaledVector(dir, -0.03);
    group.add(cone);
    const th = new THREE.Mesh(new THREE.ConeGeometry(0.04*scale, 0.1*scale, 10, 1, true), inner);
    th.quaternion.copy(cone.quaternion); th.position.copy(cone.position).addScaledVector(dir, -0.015);
    group.add(th);
  }
}
function buildChaser(){
  const g = new THREE.Group();
  const mli = new THREE.MeshStandardMaterial({ map: texMLI(), roughness: 0.55, metalness: 0.55, bumpMap: texMLI(), bumpScale: 0.6 });
  const panel = new THREE.MeshStandardMaterial({ map: texPanel(), roughness: 0.6, metalness: 0.35 });
  const white = new THREE.MeshStandardMaterial({ color: 0xdfe4ea, roughness: 0.5, metalness: 0.25 });
  const dark = new THREE.MeshStandardMaterial({ color: 0x23282f, roughness: 0.6, metalness: 0.6 });
  const steel = new THREE.MeshStandardMaterial({ color: 0x9aa4ae, roughness: 0.35, metalness: 0.9 });

  const body = new THREE.Mesh(new THREE.BoxGeometry(2.6, 1.7, 1.7), panel); g.add(body);
  const wrapT = new THREE.Mesh(new THREE.BoxGeometry(1.7, 1.74, 1.74), mli); wrapT.position.x = -0.35; g.add(wrapT);
  const svc = new THREE.Mesh(new THREE.CylinderGeometry(0.72, 0.8, 0.7, 20), mli);
  svc.rotation.z = Math.PI/2; svc.position.x = -1.6; g.add(svc);
  const engBell = new THREE.Mesh(new THREE.ConeGeometry(0.3, 0.45, 20, 1, true), dark);
  engBell.rotation.z = Math.PI/2; engBell.position.x = -2.05; g.add(engBell);

  // docking system (+X)
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.34, 0.05, 10, 28), steel);
  ring.rotation.y = Math.PI/2; ring.position.x = 1.5; g.add(ring);
  const tunnel = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.34, 0.28, 20), white);
  tunnel.rotation.z = Math.PI/2; tunnel.position.x = 1.42; g.add(tunnel);
  for (let i=0;i<3;i++){
    const petal = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.1, 0.02), steel);
    const a = i*Math.PI*2/3;
    petal.position.set(1.58, Math.cos(a)*0.28, Math.sin(a)*0.28);
    petal.lookAt(new THREE.Vector3(2.4, 0, 0)); g.add(petal);
  }
  // solar wings ±Y
  const solTex = texSolar();
  for (const s of [1,-1]){
    const yoke = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.7, 8), steel);
    yoke.position.set(-0.3, s*1.2, 0); g.add(yoke);
    const wing = new THREE.Mesh(new THREE.BoxGeometry(1.15, 3.3, 0.05),
      new THREE.MeshStandardMaterial({ map: solTex, roughness: 0.35, metalness: 0.6 }));
    wing.position.set(-0.3, s*3.2, 0); g.add(wing);
    const frame = new THREE.Mesh(new THREE.BoxGeometry(1.22, 3.38, 0.03), dark);
    frame.position.copy(wing.position).z = -0.02; g.add(frame);
  }
  // high-gain dish +Z
  const boom = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.7, 8), steel);
  boom.position.set(-0.9, 0, 1.15); g.add(boom);
  const dish = new THREE.Mesh(new THREE.SphereGeometry(0.42, 20, 12, 0, Math.PI*2, 0, 1.0), white);
  dish.position.set(-0.9, 0, 1.55); dish.rotation.x = -0.6; g.add(dish);
  // sensor pod (+X face): optical + lidar apertures
  const pod = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.6, 0.34), dark);
  pod.position.set(1.35, 0, 0.62); g.add(pod);
  const lens = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.11, 0.09, 14),
    new THREE.MeshStandardMaterial({ color: 0x0a2a3a, roughness: 0.15, metalness: 0.9, emissive: 0x0a3a50, emissiveIntensity: 0.7 }));
  lens.rotation.z = Math.PI/2; lens.position.set(1.55, 0.12, 0.62); g.add(lens);
  const lidarAp = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.08, 12),
    new THREE.MeshStandardMaterial({ color: 0x101418, roughness: 0.3, metalness: 0.8, emissive: 0x30ff70, emissiveIntensity: 0.35 }));
  lidarAp.rotation.z = Math.PI/2; lidarAp.position.set(1.55, -0.14, 0.62); g.add(lidarAp);
  world.lidarApMat = lidarAp.material;
  // whip antennas
  for (const [y,z] of [[0.6,-0.9],[-0.7,-0.9]]){
    const whip = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.9, 6), steel);
    whip.position.set(-1.1, y, z-0.4); whip.rotation.x = 0.25; g.add(whip);
  }
  addNozzles(g, THR_DEFS);
  // nav lights: red port(+Y) / green stbd(−Y) / white strobe aft
  const mkLight = (color) => new THREE.Mesh(new THREE.SphereGeometry(0.05, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x111111, emissive: color, emissiveIntensity: 2 }));
  world.navRed = mkLight(0xff2233); world.navRed.position.set(-0.3, 1.05, 0.3); g.add(world.navRed);
  world.navGrn = mkLight(0x22ff55); world.navGrn.position.set(-0.3, -1.05, 0.3); g.add(world.navGrn);
  world.navStrobe = mkLight(0xffffff); world.navStrobe.position.set(-1.95, 0, 0.5); g.add(world.navStrobe);

  // RCS plumes (children in body coords; driven by sim duty)
  world.plumes = [];
  const plumeTex = makeCanvasTex(64, (g2,s)=>{
    const gr = g2.createLinearGradient(0,0,0,s);
    gr.addColorStop(0,'rgba(190,225,255,.95)'); gr.addColorStop(0.5,'rgba(140,190,255,.4)'); gr.addColorStop(1,'rgba(90,140,255,0)');
    g2.fillStyle = gr; g2.fillRect(0,0,s,s);
  });
  for (const d of THR_DEFS){
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.09, 1.0, 10, 1, true),
      new THREE.MeshBasicMaterial({ map: plumeTex, transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
        depthWrite: false, side: THREE.DoubleSide }));
    const dir = new THREE.Vector3(...d.dir);
    // plume extends opposite thrust dir; cone base at nozzle, tip away
    cone.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0), dir.clone().negate());
    cone.position.set(...d.pos).addScaledVector(dir, -0.55);
    g.add(cone);
    world.plumes.push(cone);
  }
  // RCS id labels
  world.rcsLabels = new THREE.Group();
  THR_DEFS.forEach((d,i)=>{
    const sp = makeTextSprite(d.id, '#ffd27f', 40);
    sp.scale.set(1.1, 0.28, 1);
    sp.position.set(...d.pos).multiplyScalar(1.28);
    world.rcsLabels.add(sp);
  });
  world.rcsLabels.visible = false;
  g.add(world.rcsLabels);
  g.traverse(o => { if (o.isMesh){ o.castShadow = true; o.receiveShadow = true; } });
  return g;
}
function buildTarget(){
