  const hull = new THREE.Mesh(new THREE.CylinderGeometry(1.05, 1.05, 3.6, 22), scorch);
  hull.rotation.z = Math.PI/2; g.add(hull);
  const nose = new THREE.Mesh(new THREE.CylinderGeometry(0.75, 1.05, 0.6, 22), gray);
  nose.rotation.z = Math.PI/2; nose.position.x = 2.0; g.add(nose);
  const aft = new THREE.Mesh(new THREE.SphereGeometry(1.05, 22, 12, 0, Math.PI*2, Math.PI/2, Math.PI/2), dark);
  aft.rotation.z = Math.PI/2; aft.position.x = -1.8; g.add(aft);

  // docking port +X with visual docking target (base plate + stand-off cross)
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.36, 0.05, 10, 28), steel);
  ring.rotation.y = Math.PI/2; ring.position.x = 2.1; g.add(ring);
  const plate = new THREE.Mesh(new THREE.CircleGeometry(0.26, 20),
    new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.8, metalness: 0.2 }));
  plate.rotation.y = Math.PI/2; plate.position.x = 2.06; g.add(plate);
  const cross1 = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.28, 0.035),
    new THREE.MeshStandardMaterial({ color: 0xcccccc, emissive: 0x99ffbb, emissiveIntensity: 0.35 }));
  cross1.position.x = 2.22; g.add(cross1);
  const cross2 = cross1.clone(); cross2.rotation.x = Math.PI/2; g.add(cross2);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 0.16, 6), steel);
  post.rotation.z = Math.PI/2; post.position.x = 2.14; g.add(post);

  // one intact-but-canted wing, one shredded stub
  const solTex = texSolar();
