    const th = sim.thr[i];
    const state = th.isolated ? 'ISOLATED' : (sim.faults.thruster===i ? 'FAULT (undet.)' : 'OK');
    html += `<tr><td>${d.id}</td><td>[${d.pos.join(',')}]</td><td>[${d.dir.join(',')}]</td>` +
      `<td class="r">${(th.duty*100).toFixed(0)}%</td><td class="r">${th.cmdTot.toFixed(1)}</td>` +
      `<td class="r">${th.achTot.toFixed(1)}</td><td>${state}</td></tr>`;
  });
