};
on('spd25','click',()=>setScale(0.25)); on('spd1','click',()=>setScale(1)); on('spd4','click',()=>setScale(4));

const SCN_BTN = { nominal:'scnNominal', 'sensor-blackout':'scnBlackout', 'stuck-thruster':'scnThruster' };
function syncScenarioBtns(){
  for (const [k,id] of Object.entries(SCN_BTN)) $(id).setAttribute('aria-pressed', String(sim.scenario === k));
}
onSimReset = ()=>{
