$('ckReduced').checked = reduced;
on('ckReduced','change', ()=>{ reduced = $('ckReduced').checked; });

on('btnClearLog','click', ()=>{ $('log').innerHTML = ''; });

on('btnDiag','click', ()=>{ $('diag').hidden = false; renderDiagTable(); });
