/* ---------------- manual command inputs (keys + touch) ---------------- */
const CMD_MAP = {
  'tx+':['F',0, 1], 'tx-':['F',0,-1], 'ty+':['F',1, 1], 'ty-':['F',1,-1], 'tz+':['F',2, 1], 'tz-':['F',2,-1],
  'rp+':['T',1,-1], 'rp-':['T',1, 1], 'ry+':['T',2, 1], 'ry-':['T',2,-1], 'rr+':['T',0, 1], 'rr-':['T',0,-1],
};
const KEY_CMD = { KeyW:'tx+', KeyS:'tx-', KeyA:'ty+', KeyD:'ty-', KeyR:'tz+', KeyF:'tz-',
  ArrowUp:'rp+', ArrowDown:'rp-', ArrowLeft:'ry+', ArrowRight:'ry-', KeyQ:'rr-', KeyE:'rr+' };
const held = new Set();
function applyManualCmd(){
  const F = [0,0,0], T = [0,0,0];
  for (const c of held){
    const m = CMD_MAP[c]; if (!m) continue;
    (m[0]==='F' ? F : T)[m[1]] += m[2];
  }
  sim.manualCmd.F = F.map(x=>clamp(x,-1,1));
  sim.manualCmd.T = T.map(x=>clamp(x,-1,1));
}
document.querySelectorAll('.padCluster .btn[data-cmd]').forEach(btn=>{
  const c = btn.dataset.cmd;
  const down = (e)=>{ e.preventDefault(); held.add(c); btn.classList.add('on'); };
  const up = ()=>{ held.delete(c); btn.classList.remove('on'); };
  btn.addEventListener('pointerdown', down);
  btn.addEventListener('pointerup', up);
  btn.addEventListener('pointerleave', up);
  btn.addEventListener('pointercancel', up);
});
addEventListener('keydown', (e)=>{
  if (e.target.closest('input,select,textarea')) return;
  const cmd = KEY_CMD[e.code];
  if (cmd && !sim.auto){ e.preventDefault(); held.add(cmd); return; }
  if (e.code === 'Space' && !e.target.closest('button')){ e.preventDefault(); setPlay(engine.paused); }
  else if (e.code === 'Period'){ setPlay(false); sim.advance(CTRL_DT); }
  else if (e.code === 'Digit1') setScale(0.25);
  else if (e.code === 'Digit2') setScale(1);
  else if (e.code === 'Digit3') setScale(4);
  else if (e.code === 'KeyC'){ setCamMode(CAM_MODES[(CAM_MODES.indexOf(cam.mode)+1)%CAM_MODES.length]); }
  else if (e.code === 'Escape'){ $('diag').hidden = true; tourStop(); }
});
addEventListener('keyup', (e)=>{ const cmd = KEY_CMD[e.code]; if (cmd) held.delete(cmd); });
addEventListener('blur', ()=> held.clear());

/* ---------------- guided tour ---------------- */
const TOUR = [
  { t:'Relative orbital motion', cam:'tgt', ov:{axes:true, trail:true, pred:true, kos:false, corridor:false},
    b:'Everything here lives in the target-centred LVLH frame: V-BAR points along the orbit, R-BAR up toward zenith. Motion follows the Clohessy–Wiltshire equations, so coasting paths curve — watch the dashed predicted path. Guidance has to fight this drift, not a video-game vacuum.' },
  { t:'Truth vs. estimate', cam:'chase', ov:{cov:true, sensors:true, trail:true},
    b:'The autopilot never sees the truth state. A Kalman filter fuses lidar range/range-rate and optical bearings into an estimate — the violet ellipsoid is its 3σ position uncertainty. Kill the sensors (FAULT INJECTION) and watch it swell; restore them and watch it snap back.' },
  { t:'Keep-out sphere & corridor', cam:'tgt', ov:{kos:true, corridor:true, guides:true},
    b:'The 30 m keep-out sphere may only be entered through the green approach cone aligned with the target\'s docking axis. Anywhere else inside is an automatic abort. Because the target tumbles, the corridor itself rotates — guidance continuously replans against it.' },
  { t:'Attitude matching', cam:'dock', ov:{guides:true, corridor:true},
    b:'In the final corridor the chaser must rotate in formation with the tumbling target: port axes aligned within 4°, relative spin under 0.8°/s. The rings and the amber roll tick show the alignment; the gates panel below scores every contact condition live.' },
  { t:'Explainable autonomy', cam:'chase', ov:{trail:true, pred:true},
    b:'Every transition, hold, replan, fault call and abort is written to the autonomy log with its reason — gate values, sigma levels, safety limits. If the vehicle hesitates, the log tells you exactly why. That traceability is the point of a digital twin.' },
  { t:'Failures & FDIR', cam:'chase', ov:{},
    b:'Inject a stuck thruster: the vehicle never senses it directly. Fault detection compares commanded impulse against IMU-measured response, accumulates evidence, isolates the dead jet and re-allocates thrust with torque compensation. Scenario 3 scripts this end-to-end.' },
  { t:'Soft capture, then hard dock', cam:'dock', ov:{guides:true},
    b:'Contact inside all gates engages the soft-capture ring — a literal spring-damper that swallows residual motion before the structural latches close. Arrive too fast or misaligned and the mechanism refuses: you bounce off. Physics, not a cut-scene.' },
  { t:'Fly it yourself', cam:'cockpit', ov:{},
    b:'Switch to MANUAL: W/S/A/D/R/F translate, arrows + Q/E rotate (touch pads on mobile). The safety monitor stays armed and will still abort you. Console API: __JANUS__.reset(seed), .setScenario(name), .step(s), .snapshot(), .runSelfTest().' },
];
let tourIdx = -1, tourSaved = null;
function tourShow(){
  const s = TOUR[tourIdx];
  $('tourTitle').textContent = s.t;
  $('tourStepNum').textContent = `STEP ${tourIdx+1}/${TOUR.length}`;
  $('tourBody').textContent = s.b;
  $('btnTourPrev').disabled = tourIdx === 0;
  $('btnTourNext').textContent = tourIdx === TOUR.length-1 ? 'FINISH' : 'NEXT ▶';
  setCamMode(s.cam);
  for (const [k,v] of Object.entries(s.ov)){ ovState[k] = v; $(OV_IDS[k]).checked = v; }
  $('tour').hidden = false;
}
function tourStop(){
  if (tourIdx < 0) return;
  tourIdx = -1; $('tour').hidden = true;
  if (tourSaved){ Object.assign(ovState, tourSaved); for (const [k,id] of Object.entries(OV_IDS)) $(id).checked = ovState[k]; }
}
on('btnTour','click', ()=>{ tourSaved = { ...ovState }; tourIdx = 0; tourShow(); });
on('btnTourNext','click', ()=>{ if (tourIdx >= TOUR.length-1) tourStop(); else { tourIdx++; tourShow(); } });
on('btnTourPrev','click', ()=>{ if (tourIdx > 0){ tourIdx--; tourShow(); } });
on('btnTourExit','click', tourStop);

/* ---------------- main loop ---------------- */
let lastT = performance.now(), uiClock = 0, plotClock = 1;
function frame(now){
  requestAnimationFrame(frame);
  const dt = Math.min((now - lastT)/1000, 0.25); lastT = now;
  applyManualCmd();
  engine.tick(dt);
  updateScene(sim, dt, ovState, reduced);
  updateCamera(dt);
  uiClock += dt;
  if (uiClock > 0.12){ uiClock = 0; updateTelemetry(); drainLog(); }
  plotClock += dt;
  if (plotClock > 0.25){ plotClock = 0; drawPlots(); }
  renderer.render(scene, camera);
}
layout();
syncScenarioBtns();
updateTelemetry();
requestAnimationFrame(frame);

// initial self-test (same functions the app runs on) — populate the chip + drawer
setTimeout(()=>{ renderDiagResult(runSelfTestSuite()); }, 500);
} // end main()

