/* =====================================================================
   PART 4 — UI, CAMERAS, ENGINE LOOP, DIAGNOSTIC API
   ===================================================================== */
const $ = id => document.getElementById(id);
const on = (id, ev, fn) => $(id).addEventListener(ev, fn);

const sim = new Sim(20260716, 'nominal');
const engine = new Engine(sim);
let reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

const ovState = { axes:false, trail:true, pred:true, kos:true, corridor:true,
                  sensors:false, cov:false, vel:false, plumes:true, guides:true, rcs:false };

/* ================= diagnostic API (defined before boot so it exists even on WebGL failure) ================= */
let onSimReset = () => {};
let renderDiagResult = () => {};
window.__JANUS__ = {
  reset(seed){
    const s = (seed === undefined) ? sim.seed : (seed | 0);
    sim.reset(s, sim.scenario); onSimReset();
    return { ok: true, seed: sim.seed, scenario: sim.scenario };
  },
  setScenario(name){
    if (!['nominal','sensor-blackout','stuck-thruster'].includes(name))
      throw new Error('setScenario expects "nominal" | "sensor-blackout" | "stuck-thruster"');
    sim.reset(sim.seed, name); onSimReset();
    return { ok: true, scenario: name };
  },
  step(seconds){
    if (!(seconds >= 0) || !isFinite(seconds)) throw new Error('step(seconds) needs a non-negative finite number');
    sim.advance(seconds);
    return sim.t;
  },
  snapshot(){ return sim.snapshot(); },
  runSelfTest(){ const r = runSelfTestSuite(); renderDiagResult(r); return r; },
};

/* ================= boot ================= */
const boot = initThree($('canvasWrap'));
if (!boot.ok){
  $('fatal').hidden = false;
  $('fatalMsg').textContent = 'PROJECT JANUS could not create a WebGL context (' +
    (boot.err && boot.err.message || 'unknown error') + '). The simulation core and __JANUS__ console API remain available.';
} else {
  main();
}

function main(){
/* ---------------- camera rig ---------------- */
const CAM_MODES = ['chase','tgt','dock','cockpit','free'];
const CAM_LABEL = { chase:'CHASE · CINEMATIC', tgt:'TARGET RELATIVE', dock:'DOCKING PORT', cockpit:'COCKPIT / FWD SENSOR', free:'FREE ORBIT' };
const CAM_FOV = { chase:55, tgt:50, dock:46, cockpit:68, free:55 };
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true; controls.dampingFactor = 0.08; controls.enabled = false;
controls.minDistance = 2; controls.maxDistance = 5000;
const cam = { mode:'chase', blend:1, fromPos:new THREE.Vector3(), fromQuat:new THREE.Quaternion(), fromFov:55 };
const _e3 = new THREE.Vector3(), _m4 = new THREE.Matrix4(), _q1 = new THREE.Quaternion();

function desiredPose(dt){
  const chP = world.chaser.position, range = Math.max(chP.length(), 4);
  const pose = { pos:new THREE.Vector3(), quat:new THREE.Quaternion(), fov:CAM_FOV[cam.mode] };
  world.chaser.updateMatrixWorld();
  if (cam.mode === 'chase'){
    const toTgt = _e3.copy(chP).negate().normalize();
    const side = new THREE.Vector3().crossVectors(toTgt, new THREE.Vector3(0,1,0)).normalize();
    if (!isFinite(side.x) || side.lengthSq() < 1e-6) side.set(1,0,0);
    const sway = reduced ? 0 : Math.sin(sim.t*0.045)*0.35;
    const back = clamp(6 + range*0.045, 7, 26);
    pose.pos.copy(chP).addScaledVector(toTgt, -back).addScaledVector(side, back*(0.45+sway)).add(new THREE.Vector3(0, back*0.42, 0));
    const look = new THREE.Vector3().copy(chP).addScaledVector(toTgt, Math.min(range*0.35, 25));
    _m4.lookAt(pose.pos, look, new THREE.Vector3(0,1,0));
    pose.quat.setFromRotationMatrix(_m4);
  } else if (cam.mode === 'tgt'){
    const mid = new THREE.Vector3().copy(chP).multiplyScalar(0.45);
    const d = clamp(range*0.85, 9, 320);
    const dir = new THREE.Vector3().copy(chP).normalize();
    const side = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0,1,0)).normalize();
    if (side.lengthSq() < 1e-6) side.set(1,0,0);
    pose.pos.copy(mid).addScaledVector(side, d*0.9).add(new THREE.Vector3(0, d*0.32, 0));
    _m4.lookAt(pose.pos, mid, new THREE.Vector3(0,1,0));
    pose.quat.setFromRotationMatrix(_m4);
  } else if (cam.mode === 'dock' || cam.mode === 'cockpit'){
    const local = cam.mode === 'dock' ? new THREE.Vector3(1.05, 0, 0.45) : new THREE.Vector3(0.9, 0, 0.1);
    const ahead = cam.mode === 'dock' ? new THREE.Vector3(9, 0, 0.1) : new THREE.Vector3(9, 0, 0.1);
    pose.pos.copy(local); world.chaser.localToWorld(pose.pos);
    const look = ahead.clone(); world.chaser.localToWorld(look);
    const up = new THREE.Vector3(0, 0, 1).applyQuaternion(world.chaser.quaternion);
    _m4.lookAt(pose.pos, look, up);
    pose.quat.setFromRotationMatrix(_m4);
  }
  return pose;
}
function setCamMode(mode){
  if (mode === cam.mode) return;
  cam.mode = mode;
  cam.blend = reduced ? 1 : 0;
  cam.fromPos.copy(camera.position); cam.fromQuat.copy(camera.quaternion); cam.fromFov = camera.fov;
  controls.enabled = mode === 'free';
  if (mode === 'free'){
    controls.target.copy(world.chaser.position).multiplyScalar(0.5);
  }
  for (const m of CAM_MODES) $('cam'+({chase:'Chase',tgt:'Tgt',dock:'Dock',cockpit:'Cockpit',free:'Free'})[m]).setAttribute('aria-pressed', String(m===mode));
  $('hudCam').textContent = 'CAM · ' + CAM_LABEL[mode];
}
function resetView(){
  if (cam.mode === 'free'){
    controls.target.copy(world.chaser.position).multiplyScalar(0.5);
    const off = new THREE.Vector3(14, 8, 14).add(world.chaser.position);
    camera.position.copy(off);
  } else {
    cam.blend = reduced ? 1 : 0;
    cam.fromPos.copy(camera.position); cam.fromQuat.copy(camera.quaternion); cam.fromFov = camera.fov;
  }
}
function updateCamera(dt){
  if (cam.mode === 'free'){ controls.update(); return; }
  const pose = desiredPose(dt);
  if (cam.blend < 1){
    cam.blend = Math.min(1, cam.blend + dt/1.1);
    const k = cam.blend*cam.blend*(3-2*cam.blend);
    camera.position.lerpVectors(cam.fromPos, pose.pos, k);
    camera.quaternion.slerpQuaternions(cam.fromQuat, pose.quat, k);
    camera.fov = cam.fromFov + (pose.fov - cam.fromFov)*k;
    camera.updateProjectionMatrix();
  } else if (cam.mode === 'dock' || cam.mode === 'cockpit'){
    camera.position.copy(pose.pos); camera.quaternion.copy(pose.quat);
    if (camera.fov !== pose.fov){ camera.fov = pose.fov; camera.updateProjectionMatrix(); }
  } else {
    const k = reduced ? 1 : 1 - Math.exp(-6*dt);
    camera.position.lerp(pose.pos, k);
    camera.quaternion.slerp(pose.quat, k);
    if (Math.abs(camera.fov - pose.fov) > 0.1){ camera.fov += (pose.fov - camera.fov)*k; camera.updateProjectionMatrix(); }
  }
}

/* ---------------- resize / DPR / context loss / visibility ---------------- */
const wrap = $('canvasWrap');
function layout(){
  const w = wrap.clientWidth, h = wrap.clientHeight;
  if (w < 2 || h < 2) return;
  renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / h; camera.updateProjectionMatrix();
  sizePlots();
}
new ResizeObserver(layout).observe(wrap);
addEventListener('resize', layout);
renderer.domElement.addEventListener('webglcontextlost', (e)=>{ e.preventDefault(); $('ctxBanner').hidden = false; });
renderer.domElement.addEventListener('webglcontextrestored', ()=>{ $('ctxBanner').hidden = true; });
document.addEventListener('visibilitychange', ()=>{ lastT = performance.now(); });

/* ---------------- plots ---------------- */
class MiniPlot {
  constructor(cvId, valId, key, color, opts = {}){
    this.cv = $(cvId); this.val = $(valId); this.key = key; this.color = color;
    this.floor0 = opts.floor0 !== false; this.digits = opts.digits ?? 2;
  }
  size(){
    const r = this.cv.getBoundingClientRect(), d = Math.min(devicePixelRatio||1, 2);
    if (r.width < 2) return;
    this.cv.width = Math.round(r.width*d); this.cv.height = Math.round(r.height*d);
  }
  draw(hist, tNow){
    const g = this.cv.getContext('2d'), W = this.cv.width, H = this.cv.height;
    if (!W) return;
    g.clearRect(0,0,W,H);
    const win = 180, t0 = tNow - win;
    let lo = Infinity, hi = -Infinity;
    const pts = [];
    for (const h of hist){
      if (h.t < t0) continue;
      const v = h[this.key];
      if (!isFinite(v)) continue;
      pts.push([h.t, v]);
      if (v < lo) lo = v; if (v > hi) hi = v;
    }
    if (!pts.length){ this.val.textContent = '—'; return; }
    if (this.floor0) lo = Math.min(lo, 0);
    if (hi - lo < 1e-9) hi = lo + 1;
    const pad = (hi-lo)*0.12; hi += pad; lo -= this.floor0 ? 0 : pad;
    g.strokeStyle = 'rgba(40,57,78,.6)'; g.lineWidth = 1;
    for (let i=1;i<3;i++){ const y = H*i/3; g.beginPath(); g.moveTo(0,y); g.lineTo(W,y); g.stroke(); }
    g.strokeStyle = this.color; g.lineWidth = Math.min(devicePixelRatio||1,2) * 1.2;
    g.beginPath();
